const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define location
  const lat = 29.135547;
  const lon = -1.187011;
  const point = ee.Geometry.Point([lon, lat]);
  const buffer = point.buffer(5000); // 5km buffer for analysis

  // Define time periods
  const earlyStart = '2024-08-01';
  const earlyEnd = '2024-08-20';
  const lateStart = '2024-09-20';
  const lateEnd = '2024-10-10';

  // Function to calculate water extent
  function calculateWaterExtent(startDate, endDate, label) {
    const col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(buffer)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    const size = col.size().getInfo();
    console.log(`${label} Images found: ${size}`);

    if (size === 0) {
      return null;
    }

    // Composite - use median to reduce noise
    const composite = col.median();

    // Calculate NDWI for water detection
    // NDWI = (GREEN - NIR) / (GREEN + NIR)
    const ndwi = composite.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0.3)
    const waterMask = ndwi.gt(0.3);

    // Count water pixels
    const waterPixels = waterMask.reduceRegion(
      {
        reducer: ee.Reducer.sum(),
        geometry: buffer,
        scale: 10,
        maxPixels: 1e9
      }
    ).get('NDWI').getInfo();

    // Total valid pixels
    const totalPixels = composite.select('B8').reduceRegion(
      {
        reducer: ee.Reducer.count(),
        geometry: buffer,
        scale: 10,
        maxPixels: 1e9
      }
    ).get('B8').getInfo();

    console.log(`${label} - Water pixels: ${waterPixels}, Total: ${totalPixels}`);

    return waterPixels;
  }

  // Calculate for both periods
  const earlyWater = calculateWaterExtent(earlyStart, earlyEnd, 'Early (Aug 12)');
  const lateWater = calculateWaterExtent(lateStart, lateEnd, 'Late (Sep 29)');

  // Validation
  if (earlyWater === null || lateWater === null) {
    console.log('No data available for one or both periods');
    console.log('C1');
    return;
  }

  if (earlyWater === 0 && lateWater === 0) {
    console.log('No valid water pixels detected in both periods');
    console.log('C2');
    return;
  }

  if (earlyWater === null || lateWater === null || isNaN(earlyWater) || isNaN(lateWater)) {
    console.log('Calculation failure');
    console.log('C3');
    return;
  }

  // Compare water extent
  console.log(`Water extent comparison: Early=${earlyWater}, Late=${lateWater}`);
  console.log(`Change: ${lateWater - earlyWater} pixels`);

  if (lateWater > earlyWater) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
